/// <summary>
/// Transfer order tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningLinesTmp))]
public METTransferOrderLoadPlanningLinesTmp getTransferOrder()
{
    select transferOrderLoadPlanningLinesTmp;
    return transferOrderLoadPlanningLinesTmp;
}

/// <summary> /// Parses the report parameters and fills the <c>transferOrderLoadPlanningAidLinesTmp</c> tables with data. /// </summary> public void processReport() { contract = this.parmDataContract() as METTransferOrderLoadPlanningContract;
METTransferOrderLoadPlanningLines metTransferOrderLoadPlanningLinesTmp;
CreatedTransactionId createdTransactionId = contract.parmTransaction();
transferOrderLoadPlanningLinesTmp.setConnection(this.parmUserConnection());
insert_recordset transferOrderLoadPlanningLinesTmp (FromWareHouseName, ToWareHouseName, StopNumber, Suburb, ConfirmedShipDate, Route, RouteStop, StagingLane, BrokenCase, Cases, TotalVolume, TotalWeight, InternalCustomer, OrderSplitCategoryCode, TransferId, LineNum) select FromWareHouseName, ToWareHouseName, StopNumber, Suburb, ConfirmedShipDate, Route, RouteStop, StagingLane, BrokenCase, Cases, TotalVolume, TotalWeight, InternalCustomer, OrderSplitCategoryCode, TransferId, LineNum from metTransferOrderLoadPlanningLinesTmp where metTransferOrderLoadPlanningLinesTmp.CreatedTransactionId == createdTransactionId;
// clear data inserted from controller class delete_from metTransferOrderLoadPlanningLinesTmp where metTransferOrderLoadPlanningLinesTmp.CreatedTransactionId == createdTransactionId; }
